/**
 * Collapses the project into the two files Apps Script actually needs.
 *
 * The repository is split into fifteen files because that is how the code stays
 * readable. Apps Script does not care: every .gs shares one global scope, so
 * they concatenate, and the two HTML partials are only separate because
 * HtmlService needs a name to include them by -- inlined, they are one page.
 *
 * Recreating fifteen files by hand in a browser editor is twenty minutes of
 * clicking and a chance to mistype a filename. Two pastes is not.
 *
 *   node tools/build-deploy-bundle.js
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'apps-script');
const OUT = path.join(ROOT, 'deploy');

/* Config first so the constants exist before anything reads them, then the
 * rest in dependency order, with the entry points last. */
const ORDER = [
  '00_Config.gs', '01_Store.gs', '02_Auth.gs', '03_People.gs', '04_Photos.gs',
  '05_Relations.gs', '06_Kinship.gs', '07_Titles.gs', '08_Matching.gs',
  '09_Merge.gs', '10_Admin.gs', '11_Api.gs', '12_Dev.gs', '13_Layout.gs',
  '14_Picker.gs', 'Code.gs'
];

fs.mkdirSync(OUT, { recursive: true });

const banner = (name) =>
  '\n/* ================================================================== *\n' +
  ' * ' + name.padEnd(62) + ' *\n' +
  ' * ================================================================== */\n\n';

let code = [
  '/**',
  ' * Pokok Keluarga -- the whole server, in one file.',
  ' *',
  ' * Generated by tools/build-deploy-bundle.js from the fifteen source files in',
  ' * apps-script/. Edit those, not this: run the script again to rebuild.',
  ' *',
  ' * Paste this into Code.gs in the Apps Script editor, paste Index.html into an',
  ' * HTML file named Index, and follow docs/SETUP.md from step 3.',
  ' */',
  ''
].join('\n');

for (const file of ORDER) {
  const full = path.join(SRC, file);
  if (!fs.existsSync(full)) throw new Error('Missing source file: ' + file);
  code += banner(file) + fs.readFileSync(full, 'utf8').replace(/\s+$/, '') + '\n';
}

// The manifest still ships separately; Apps Script has its own editor for it.
fs.writeFileSync(path.join(OUT, 'Code.gs'), code);
fs.writeFileSync(path.join(OUT, 'appsscript.json'),
  fs.readFileSync(path.join(SRC, 'appsscript.json'), 'utf8'));

/* The two partials are inlined where HtmlService would have included them, so
 * the interface is a single file too. */
let page = fs.readFileSync(path.join(SRC, 'Index.html'), 'utf8');
for (const partial of ['Styles', 'Client']) {
  const body = fs.readFileSync(path.join(SRC, partial + '.html'), 'utf8').replace(/\s+$/, '');
  const tag = new RegExp("<\\?!=\\s*include\\('" + partial + "'\\);?\\s*\\?>");
  if (!tag.test(page)) throw new Error('No include() call found for ' + partial);
  page = page.replace(tag,
    '<!-- ' + partial + '.html, inlined by tools/build-deploy-bundle.js -->\n' + body);
}
fs.writeFileSync(path.join(OUT, 'Index.html'), page);

const kb = (p) => Math.round(fs.statSync(path.join(OUT, p)).size / 1024) + ' KB';
console.log('deploy/Code.gs          ' + kb('Code.gs'));
console.log('deploy/Index.html       ' + kb('Index.html'));
console.log('deploy/appsscript.json  ' + kb('appsscript.json'));
console.log('\nTwo files to paste, plus the manifest.');
